/* ===== Round 2 design-system documentation ===== */
DEV2.push('Round 2: checklist & data model');
const _dsComp3=dsComp2;
dsComp2=function(){const sh=(l,h)=>`<div class="card pad stack"><h3>${l}</h3>${h}</div>`;const sv=allServices()[0],v=allVideos().find(x=>x.m.status==='approved');
 return _dsComp3()+`<div class="card pad" style="background:var(--primary-soft)"><b>${t('Round 2 components')}</b></div>
 ${H2('Category pill + subcategory pill row')}${sh('Sticky, scrollable, long Hindi text wraps',`${pillRow([{k:'',label:t('All'),n:12},{k:'a',label:'Wedding & Events',n:6},{k:'b',label:'टेंट, लाइटिंग व सजावट का सामान और किराये की सेवाएँ',n:3},{k:'c',label:'Mechanic & Repair',n:5}],'a','noop')}${pillRow([{k:'',label:t('All subcategories'),n:6},{k:'x',label:'Tent & Lighting',n:2},{k:'y',label:'DJ & Sound',n:2}],'y','noop','padding-top:4px')}`)}
 ${H2('Service card')}${sh('Image, subcategory tag, provider, price, rating, distance, availability, offer badge, quick actions',`<div class="shopgrid">${allServices().slice(0,3).map(serviceCard).join('')}</div>`)}
 ${H2('Service details layout')}${sh('Carousel, price, included/excluded, provider + follow, videos, enquiry, reviews, FAQs',`<a class="btn p sm" style="justify-self:start" href="#service-${sv.id}">${t('Open a service details page')}</a>`)}
 ${H2('Follow button, reels player, linked-product strip, video grid')}${sh('States: Follow · Following (with bell) · unfollow confirm',`<div class="row wrap-r">${followBtn('b5')}<button class="btn p sm" data-act="follow" data-id="b4">+ ${t('Follow')}</button></div><div class="row wrap-r"><a class="btn p sm" href="#videos">${ic('play',14)} ${t('Open Reels player')}</a></div><div class="rlinks" style="background:#222;padding:10px;border-radius:12px">${(v.m.tags||[]).map(tagItem).filter(Boolean).slice(0,2).map(l=>linkMini(l,v.m.id)).join('')}</div><div class="grid auto-s">${allVideos().filter(x=>x.m.status==='approved').slice(0,4).map(vidCard).join('')}</div>`)}
 ${H2('Media-consent toggle, search result groups')}${sh('Default on, can be changed per item',mediaConsent(true,'noop'))}${sh('All tab: grouped sections with “See all”',`${grpHead('Services',4,'s','Related services for AC')}<div class="small muted">${t('Products · Shops · Services · Videos each have a header and a See all link.')}</div>`)}`};
const flowStep=(l,o)=>o.href?`<a class="chip" href="#${o.href}" data-act="flowGo" data-r="${o.href}">${l}</a>`:`<button class="chip" data-act="${o.act}" ${Object.entries(o.d||{}).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')}>${l}</button>`;
const FLOWS3=[
 ['(a) Home category → Explore (pre-selected) → product',[['Home',{href:'home'}],['Electronics tile',{act:'flowCat',d:{id:'electronics'}}],['Product ▸ Split AC',{href:'prod-p50'}]]],
 ['(b) Service category → Services → subcategory filter → service → enquiry',[['Home',{href:'home'}],['Wedding & Events tile',{act:'flowCat',d:{id:'wedding'}}],['Tick DJ & Sound + Tent & Lighting',{act:'flowSvc'}],['Service card',{href:'service-s7-sv0'}],['Send enquiry',{href:'service-s7-sv0'}]]],
 ['(c) Offer → product details',[['Home offers',{href:'home'}],['AC offer (2 products → list)',{act:'offerGo',d:{id:'of8'}}],['Noodles offer (out of stock)',{act:'offerGo',d:{id:'of6'}}],['Expired offer',{act:'offerGo',d:{id:'of5'}}],['Service offer',{act:'offerGo',d:{id:'of7'}}]]],
 ['(d) Play icon → Reels → follow, like, share → linked product',[['Play icon',{href:'videos'}],['Follow · like · share',{href:'videos-m5'}],['Linked product strip',{href:'prod-p52'}]]],
 ['(e) Search “AC” and “iPhone 15” → grouped results → service details',[['Search AC',{act:'flowSq',d:{q:'AC'}}],['Search iPhone 15',{act:'flowSq',d:{q:'iPhone 15'}}],['Service details',{href:'service-s11-sv1'}]]],
 ['(f) Vendor uploads video → links products → Gallery option → public Reels and Gallery',[['Vendor ▸ Gallery & media',{href:'vmedia'}],['Admin ▸ Approve video',{href:'avideos'}],['Public Reels',{href:'videos'}],['Public Gallery',{href:'biz-b4'}]]]];
A.flowCat=el=>{S.role='customer';save();applyCat(el.dataset.id);go('explore')};
A.flowSvc=()=>{S.role='customer';save();applyCat('wedding');UI.exF.s.subs=['dj-sound','tent-lighting'];go('explore')};
A.flowSq=el=>{S.role='customer';UI.q=el.dataset.q;UI.stab='all';save();go('search')};
const RMAP=[['1A','Shop by Category tile → Explore with category pre-applied in all three tabs, tab counts, shareable URL, back keeps scroll','Customer ▸ Home → Explore','home'],['1B','Local Services tile → Explore ▸ Services (subcategories pre-selected)','Customer ▸ Home → Explore','home'],['1C','Offer card → product / service / filtered list; expired and out-of-stock states','Customer ▸ Home, Offers, Product page','offers'],['1D','Three clickable flows','Design system ▸ Patterns & flows','design'],['1E','Services filter with subcategory multi-select (sheet, sidebar, tablet bar)','Explore ▸ Services · Search ▸ Services · service category page','explore'],['2','Business page: Products & Services section with pills','Customer ▸ shop / provider page','biz-b4'],['3','Videos and reels feed, play icon, follow, like, share, linked strip','Customer ▸ Videos','videos'],['4','Service card and service details page','Customer ▸ any service card','service-s7-sv0'],['5','Product page: Videos & Reels section and carousel','Customer ▸ Product (iPhone 16)','prod-p45'],['6','Smart search: All | Products | Shops | Services | Videos with keyword mapping','Customer ▸ Search','search'],['7','Gallery and media rules (consent toggle, public gallery, moderation)','Vendor ▸ Gallery & media · public Gallery','biz-b4'],['8','Dashboards: services, videos & reels manager, followers, gallery, pills; admin tree, moderation, keywords','Vendor / Provider / Admin','vservices'],['9','Data relationships and routes','Design system ▸ Round 2 checklist & data model','design']];
const RROLE={vservices:'vendor',avideos:'admin'};
function dsR2(){return `${H2('Round 2 checklist: every change and where it is shown')}${tbl(['Change','Requirement','Where','Open'],RMAP.map(r=>[`<b>${r[0]}</b>`,esc(r[1]),esc(r[2]),`<a class="btn p sm" href="#${r[3]}" data-act="${RROLE[r[3]]?'asRole':'flowGo'}" data-role="${RROLE[r[3]]||'customer'}" data-r="${r[3]}">${t('Open')}</a>`]))}
 ${H2('Round 2 flows (a to f)')}<div class="stack">${FLOWS3.map(([n,steps])=>`<div class="card pad stack"><b>${n}</b><div class="row wrap-r" style="gap:6px">${steps.map(([l,o],i)=>`${i?ic('cr',16):''}${flowStep(`${i+1}. ${l}`,o)}`).join('')}</div></div>`).join('')}</div>
 ${H2('Data relationships (Change 9)')}<div class="card pad stack"><pre class="pre" style="max-height:none">Category ──< Subcategory ──< Service type
   │                │
   │                └──< Service  (each service has ONE subcategory)
Product >── Category            Provider ──< Service     Provider "expert in" >──< Subcategory (many)
Business ──< Product            Business ──< Service     (a business or provider can own both)
Video ──< linked Product / Service   (tags)      Video >── Owner (Business or Provider)
User ──< Follow >── Owner       User ──< Like >── Video  User ──< Heart >── Photo / Video
Keyword ──< Category / Subcategory / Product tag         Offer >──< Product / Service / Shop</pre>
 <dl class="kv" style="grid-template-columns:1fr"><dt><b>Explore</b></dt><dd style="text-align:left">${t('Reads Category (pre-applied in all tabs), Product ↔ Category/Subcategory, Service ↔ Subcategory. Services filter URL: tab=services&category=wedding-events&subcategory=dj-sound,tent-lighting. Counts per subcategory are computed from Service.sub after the other filters.')}</dd><dt><b>Search</b></dt><dd style="text-align:left">${t('Normalises the query (Hindi, Hinglish, typos), looks it up in Keyword ↔ Category/Subcategory/Tag, then returns Products (name, tags), Shops (related category + owners of matches), Services (name or mapped subcategory) and Videos (text or linked items).')}</dd><dt><b>Reels</b></dt><dd style="text-align:left">${t('Feed = approved Videos. Following uses Follow, Nearby uses Owner distance, Offers/Products/Services use the Video ↔ linked items. Like and Follow are per user.')}</dd><dt><b>Offers</b></dt><dd style="text-align:left">${t('Offer ↔ Product/Service decides the target: one product → product page, one service → service page, several products → filtered Explore list, none → shop page. Expiry and stock are read on arrival.')}</dd></dl></div>
 ${H2('Routes and sitemap (new and changed)')}${tbl(['Production URL','Prototype route','Purpose'],[['/explore?tab=products&category=electronics','#explore (state in query)','Category deep-link, all tabs'],['/explore?tab=services&category=wedding-events&subcategory=dj-sound,tent-lighting','#explore','Services filter, shareable'],['/videos · /videos/:id','#videos · #videos-ID','Reels feed and start at a video'],['/service/:slug','#service-ID','Service details'],['/product/:slug','#prod-ID','Product details (offer banner, videos)'],['/search?q=AC','#search','All | Products | Shops | Services | Videos'],['/shop/:slug · /provider/:slug','#biz-ID · #svc-ID','Products & Services, Gallery, Videos / Reels tabs'],['/vendor/services · /vendor/media · /vendor/followers','#vservices · #vmedia · #vfollow','Dashboards'],['/admin/videos · /admin/keywords','#avideos · #akeys','Moderation, keyword mapping']])}
 ${H2('State coverage for Round 2 screens')}${tbl(['State','Where'],[['Loading','Route skeletons, Reels skeleton, filter results skeleton, Slow connection toggle'],['Empty','No services/products for category (Clear category + suggestions), empty Following, no videos nearby, no services in a business, no video results'],['Error','Videos fail to load with Retry (Demo ▸ videos fail), page error state'],['Offline','Reels offline overlay (turn the device offline)'],['No permission','Admin without Reviews/Catalog permission on video moderation and keywords'],['Unavailable','Removed or rejected video link, expired offer, out-of-stock offer']])}
 ${H2('Assumptions and limits')}<div class="card pad"><ul class="t2" style="margin:0;padding-left:20px"><li>${t('Reels use poster art with a simulated progress bar and tap-to-pause. Real playback needs video hosting; the Open in YouTube / Instagram link always works.')}</li><li>${t('Mute is a UI state only. There is no audio in the prototype.')}</li><li>${t('Search keyword intelligence is a mapping table plus small typo tolerance, not a full search engine.')}</li><li>${t('A provider can list one or several “expert in” subcategories; each individual service has exactly one subcategory.')}</li><li>${t('The tablet horizontal filter bar uses the same component (a Filters button with a count badge). The hosted preview may not keep a query string; the URL format is built in and works on your own hosting.')}</li><li>${t('Hindi is partial: customer screens and main labels are translated, many new admin and dashboard strings still show in English.')}</li><li>${t('Video upload is simulated (link-based). Gallery photos are placeholder art.')}</li></ul></div>`}
const _dsInv3=dsInv2;
INV3.push(['Explore: category deep-link, tab counts, category pill','Customer','#explore','Pill, Tabs with counts, Empty state','default, empty (Clear category), loading'],['Offer → product/service/list + expired + out-of-stock','Customer','#offers · #prod-ID · #service-ID','Offer banner','expired, out of stock'],['Products & Services section, Gallery, Videos / Reels tabs','Customer','#biz-ID · #svc-ID','Pills, Service card, Gallery grid','empty, filtered'],['Service details page','Customer','#service-ID','Carousel, Provider card, Enquiry form','success, no videos'],['Videos / Reels feed','Customer','#videos · #videos-ID','Reels player, Follow, Linked strip','empty Following, nearby, failed, offline, removed, data saver'],['Smart search with groups','Customer','#search','Grouped results, Suggestions','no results, typo, Hindi'],['Dashboards: services, videos & reels, followers, pills','Vendor / Provider','#vservices · #vmedia · #vfollow','Service form, Video manager, Chart','pending, rejected'],['Admin: category tree, keyword mapping, video moderation','Admin / Super Admin','#acats · #akeys · #avideos','Tree, Mapping tool, Queue','no permission, empty']);
V.design=()=>{const tab=UI.dtab||0;return `<div class="stack-lg"><div class="row between wrap-r"><div><h1>${t('ApnaTown design system')}</h1><p class="t2">${t('Tokens, components, patterns and the screen inventory. Everything here is rendered with the live app styles.')}</p></div><button class="btn g sm" data-act="theme" data-v="${(document.documentElement.dataset.theme==='dark')?'light':'dark'}">${ic('moon',16)} ${t('Toggle dark mode')}</button></div><div class="tabs">${DEV2.map((l,i)=>`<button class="${tab===i?'on':''}" data-act="dtab" data-v="${i}">${t(l)}</button>`).join('')}</div>${[dsFound,dsComp2,dsPat2,dsInv2,dsCheck,dsR2][tab]()}</div>`};
